function actionColor(a){ return a==='downgrade' ? '#b33a3a' : a==='default' ? '#4f4a45' : a==='upgrade' ? '#2f7d5a' : '#a7a099'; }
function actionSymbol(a){ return a==='downgrade' ? d3.symbolTriangle : a==='default' ? d3.symbolCross : a==='upgrade' ? d3.symbolTriangle : d3.symbolCircle; }
function render(){
  var svg=d3.select('#viz');
  var width=1484, height=720;
  svg.attr('viewBox',[0,0,width,height]).attr('preserveAspectRatio','xMidYMid meet');
  svg.selectAll('*').remove();

  var countries=['Argentina','Sri Lanka','Ghana','Turkey','Pakistan','Egypt','South Africa','Brazil'];
  var debt2024=new Map(DATA.external_debt_to_gdp.data.filter(d=>d.year===2024).map(d=>[d.country,d.debt_gdp_pct]));
  var dep2024=new Map(DATA.currency_depreciation.data.filter(d=>d.year===2024).map(d=>[d.country,d.depreciation_pct]));
  countries.sort((a,b)=>(debt2024.get(b)+dep2024.get(b))-(debt2024.get(a)+dep2024.get(a)));

  var margin={top:74,right:38,bottom:48,left:150};
  var timelineW=880, gap=54, panelW=320;
  var x=d3.scaleLinear().domain([2021,2025]).range([margin.left, margin.left+timelineW]);
  var y=d3.scaleBand().domain(countries).range([margin.top+86, height-margin.bottom]).paddingInner(.18).paddingOuter(.06);
  var fedY=d3.scaleLinear().domain([0,6]).range([margin.top+70, margin.top+2]);
  var heat=d3.scaleSequential().domain([0,86]).interpolator(d3.interpolateRgbBasis(['#f5e5cb','#e2a967','#c86943','#9e2f2f']));
  var exposureX=d3.scaleLinear().domain([0,90]).range([margin.left+timelineW+gap, margin.left+timelineW+gap+panelW]);

  var defs=svg.append('defs');
  var grad=defs.append('linearGradient').attr('id','fedGrad').attr('x1','0%').attr('x2','100%');
  grad.append('stop').attr('offset','0%').attr('stop-color','#58799a');
  grad.append('stop').attr('offset','58%').attr('stop-color','#244a73');
  grad.append('stop').attr('offset','100%').attr('stop-color','#b95635');
  defs.append('filter').attr('id','shadow').attr('x','-20%').attr('y','-20%').attr('width','140%').attr('height','140%')
    .append('feDropShadow').attr('dx',0).attr('dy',2).attr('stdDeviation',2).attr('flood-color','#000').attr('flood-opacity',.18);

  svg.append('text').attr('class','section-title').attr('x',margin.left).attr('y',30).text('Shared timeline: Fed rate, FX depreciation intensity, and rating actions');
  svg.append('text').attr('class','section-title').attr('x',exposureX.range()[0]).attr('y',30).text('2024 exposure spectrum');

  var years=[2021,2022,2023,2024,2025];
  var grid=svg.append('g').attr('class','grid');
  years.slice(0,4).forEach(function(yr){ grid.append('line').attr('x1',x(yr)).attr('x2',x(yr)).attr('y1',margin.top+78).attr('y2',height-margin.bottom+8); });
  var stressX0=x(2022.25), stressX1=x(2023.75);
  svg.append('rect').attr('x',stressX0).attr('y',margin.top-2).attr('width',stressX1-stressX0).attr('height',height-margin.top-margin.bottom+28).attr('fill','#b95635').attr('opacity',.075).attr('rx',10);
  svg.append('text').attr('class','small-label').attr('x',(stressX0+stressX1)/2).attr('y',margin.top+15).attr('text-anchor','middle').attr('fill','#8e422c').text('steep Fed-hike / downgrade clustering window');

  var rateLine=d3.line().x(d=>x(dateToDecimal(d.date))).y(d=>fedY(d.rate_pct)).curve(d3.curveMonotoneX);
  svg.append('path').datum(DATA.fed_funds_rate.data).attr('d',rateLine).attr('fill','none').attr('stroke','url(#fedGrad)').attr('stroke-width',4.5).attr('stroke-linecap','round').attr('filter','url(#shadow)');
  svg.selectAll('.fed-dot').data(DATA.fed_funds_rate.data).join('circle').attr('class','fed-dot').attr('cx',d=>x(dateToDecimal(d.date))).attr('cy',d=>fedY(d.rate_pct)).attr('r',4.5).attr('fill','#244a73').attr('stroke','#fffdf8').attr('stroke-width',2);
  svg.append('g').attr('class','axis').attr('transform','translate('+margin.left+',0)').call(d3.axisLeft(fedY).ticks(3).tickFormat(d=>d+'%')).call(g=>g.select('.domain').remove());
  svg.append('text').attr('class','small-label').attr('x',margin.left-4).attr('y',margin.top-4).attr('text-anchor','end').text('Fed funds');

  var xAxis=d3.axisTop(x).tickValues([2021,2022,2023,2024]).tickFormat(d=>String(d));
  svg.append('g').attr('class','axis').attr('transform','translate(0,'+(margin.top+76)+')').call(xAxis).call(g=>g.select('.domain').remove());

  countries.forEach(function(c){
    var rowY=y(c), rowH=y.bandwidth();
    svg.append('text').attr('class','country-label').attr('x',18).attr('y',rowY+rowH*.43).text(c);
    svg.append('text').attr('class','country-sub').attr('x',18).attr('y',rowY+rowH*.76).text('2024: debt '+debt2024.get(c).toFixed(1)+'%, FX '+dep2024.get(c).toFixed(1)+'%');
    var dep=DATA.currency_depreciation.data.filter(d=>d.country===c);
    dep.forEach(function(d){
      svg.append('rect').attr('x',x(d.year)).attr('y',rowY).attr('width',x(d.year+1)-x(d.year)-3).attr('height',rowH).attr('rx',8)
        .attr('fill',heat(d.depreciation_pct)).attr('stroke','rgba(45,35,24,.16)');
      svg.append('text').attr('x',x(d.year+.5)).attr('y',rowY+rowH*.58).attr('text-anchor','middle').attr('font-size',rowH>42?12:11).attr('font-weight',720)
        .attr('fill',d.depreciation_pct>45?'#fffaf0':'#3a2d22').text(d.depreciation_pct.toFixed(1));
    });
    var events=DATA.sovereign_rating_changes.data.filter(d=>d.country===c && d.action!=='affirm');
    events.forEach(function(e, i){
      var px=x(dateToDecimal(e.date)), py=rowY+rowH+12+(i%2)*11;
      var sym=d3.symbol().type(actionSymbol(e.action)).size(e.action==='default'?95:85);
      var g=svg.append('g').attr('transform','translate('+px+','+py+')');
      g.append('path').attr('d',sym).attr('fill',actionColor(e.action)).attr('stroke','#fffdf8').attr('stroke-width',1.8).attr('transform',e.action==='upgrade'?'rotate(180)':'');
      g.append('title').text(c+' '+e.date+' '+e.action+' to '+e.rating_level);
    });
  });

  // Exposure panel grid and lollipops
  svg.append('g').attr('class','axis').attr('transform','translate(0,'+(margin.top+76)+')').call(d3.axisTop(exposureX).tickValues([0,30,60,90]).tickFormat(d=>d+'%')).call(g=>g.select('.domain').remove());
  [0,30,60,90].forEach(function(v){ svg.append('line').attr('x1',exposureX(v)).attr('x2',exposureX(v)).attr('y1',margin.top+86).attr('y2',height-margin.bottom).attr('stroke','rgba(45,35,24,.09)').attr('stroke-dasharray','2 5'); });
  svg.append('text').attr('class','small-label').attr('x',exposureX(22)).attr('y',margin.top+50).attr('fill','#244a73').text('external debt-to-GDP');
  svg.append('text').attr('class','small-label').attr('x',exposureX(61)).attr('y',margin.top+50).attr('fill','#b95635').text('currency depreciation');

  countries.forEach(function(c){
    var yy=y(c)+y.bandwidth()/2;
    var dv=debt2024.get(c), fv=dep2024.get(c);
    svg.append('line').attr('x1',exposureX(0)).attr('x2',exposureX(Math.max(dv,fv))).attr('y1',yy).attr('y2',yy).attr('stroke','rgba(45,35,24,.18)').attr('stroke-width',2);
    svg.append('line').attr('x1',exposureX(dv)).attr('x2',exposureX(fv)).attr('y1',yy).attr('y2',yy).attr('stroke','#a98b70').attr('stroke-width',5).attr('stroke-linecap','round').attr('opacity',.38);
    svg.append('circle').attr('cx',exposureX(dv)).attr('cy',yy-7).attr('r',7).attr('fill','#244a73').attr('stroke','#fffdf8').attr('stroke-width',2);
    svg.append('circle').attr('cx',exposureX(fv)).attr('cy',yy+7).attr('r',7).attr('fill','#b95635').attr('stroke','#fffdf8').attr('stroke-width',2);
    var labelX=exposureX(Math.max(dv,fv))+13;
    svg.append('text').attr('x',Math.min(labelX, width-36)).attr('y',yy+4).attr('font-size',12).attr('font-weight',760).attr('fill','#211b16').text(dv.toFixed(1)+' / '+fv.toFixed(1));
  });

  // Heat scale
  var lg=svg.append('g').attr('transform','translate('+(margin.left+timelineW-198)+','+(height-24)+')');
  var grad2=defs.append('linearGradient').attr('id','heatGrad').attr('x1','0%').attr('x2','100%');
  ['#f5e5cb','#e2a967','#c86943','#9e2f2f'].forEach((col,i)=>grad2.append('stop').attr('offset',(i/3*100)+'%').attr('stop-color',col));
  lg.append('rect').attr('width',168).attr('height',9).attr('rx',5).attr('fill','url(#heatGrad)').attr('stroke','rgba(45,35,24,.16)');
  lg.append('text').attr('x',-8).attr('y',9).attr('text-anchor','end').attr('class','small-label').text('0%');
  lg.append('text').attr('x',176).attr('y',9).attr('class','small-label').text('86%');
  lg.append('text').attr('x',84).attr('y',-7).attr('text-anchor','middle').attr('class','small-label').text('FX depreciation heat');
}
if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); } else { render(); }
</script>
</body>
</html>
'''
html = html.replace('__DATA__', json.dumps(D, separators=(',',':')))
out=pathlib.Path('/app/output')
out.mkdir(parents=True, exist_ok=True)
(out/'result.html').write_text(html)
print('/app/output/result.html')
